CREATE TABLE IF NOT EXISTS tenants(id text primary key,subscription_id text unique not null,business_name text not null,owner_email text not null,plan_slug text not null,plan_limits jsonb not null default '{}',status text not null check(status in('ACTIVE','SUSPENDED')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS provisioning_events(event_id text primary key,tenant_id text not null references tenants(id),created_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS product_sessions(token_hash text primary key,tenant_id text not null references tenants(id),user_id text not null,email text not null,expires_at timestamptz not null,created_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS properties(id bigserial primary key,tenant_id text not null references tenants(id),title jsonb not null,description jsonb not null default '{}',city text not null,area text not null,price_minor bigint not null check(price_minor>=0),currency text not null default 'ILS',listing_type text not null check(listing_type in('sale','rent')),property_type text not null,beds integer not null default 0,baths integer not null default 0,size_sqm integer not null default 0,images jsonb not null default '[]',status text not null default 'DRAFT',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
CREATE INDEX IF NOT EXISTS properties_tenant_status_idx ON properties(tenant_id,status);
CREATE TABLE IF NOT EXISTS leads(id bigserial primary key,tenant_id text not null references tenants(id),property_id bigint references properties(id),type text not null,name text not null,email text not null,phone text,message text,status text not null default 'NEW',created_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS favorites(id bigserial primary key,tenant_id text not null references tenants(id),user_email text not null,property_id bigint not null references properties(id) on delete cascade,created_at timestamptz not null default now(),unique(tenant_id,user_email,property_id));
